param([Parameter(Mandatory=$true)][string]$RunDirectory,[Parameter(Mandatory=$true)][int]$ProcessId,[Parameter(Mandatory=$true)][string]$DocumentName,[Parameter(Mandatory=$true)][string]$PreviewDllPath,[Parameter(Mandatory=$true)][string]$PreviewDllSha256,[Parameter(Mandatory=$true)][string]$ControllerArgumentsJsonPath)
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../..'));$controller=Join-Path ([IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../..'))) 'reference/project-orchestration/scripts/invoke_post_ordinary_rescue_audit_visual_v35.ps1';$watcher=Join-Path ([IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../..'))) 'reference/project-orchestration/scripts/watch_tianzheng_dialogs.ps1';$run=[IO.Path]::GetFullPath($RunDirectory);$dll=[IO.Path]::GetFullPath($PreviewDllPath);$argumentsPath=[IO.Path]::GetFullPath($ControllerArgumentsJsonPath);foreach($p in @($controller,$watcher,$dll,$argumentsPath)){if(-not(Test-Path -LiteralPath $p -PathType Leaf)-or-not$p.StartsWith($root+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'POST_ORDINARY_TRUSTED_V36_PATH'}};if((Get-FileHash $dll -Algorithm SHA256).Hash-cne$PreviewDllSha256.ToUpperInvariant()){throw 'POST_ORDINARY_TRUSTED_V36_HASH'};$arguments=Get-Content -LiteralPath $argumentsPath -Raw -Encoding UTF8|ConvertFrom-Json -AsHashtable;$arguments['RunDirectory']=$RunDirectory;if([int]$arguments['ProcessId']-ne$ProcessId-or[string]$arguments['DocumentName']-cne$DocumentName-or[string]$arguments['PreviewDllSha256']-cne$PreviewDllSha256){throw 'POST_ORDINARY_TRUSTED_V36_ARGUMENT_IDENTITY'}
$log=Join-Path $run 'trusted_dialogs.jsonl';$job=Start-Job -ScriptBlock {param($Watcher,$OwnedProcessId,$Log,$Path,$Hash,$Title,$TrustedRoot);Set-ExecutionPolicy -Scope Process -ExecutionPolicy Bypass -Force;&$Watcher -ProcessId $OwnedProcessId -LogPath $Log -ExpectedTrustedScriptPaths @($Path) -ExpectedTrustedScriptSha256s @($Hash) -TrustedScriptRoot $TrustedRoot -MaxTrustedScriptAutoDismissCount 1 -RequiredMainTitle $Title -TimeoutSeconds 300 -QuietSeconds 0} -ArgumentList $watcher,$ProcessId,$log,$dll,$PreviewDllSha256,$DocumentName,$root
try{&$controller @arguments}finally{if($job.State-eq'Running'){Stop-Job $job -ErrorAction SilentlyContinue};Receive-Job $job -ErrorAction SilentlyContinue|Out-Null;Remove-Job $job -Force -ErrorAction SilentlyContinue}
